import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"晉","description":"焦氏易林注 - 晉","frontmatter":{"title":"晉","description":"焦氏易林注 - 晉"},"headers":[],"relativePath":"zh/classics/jiaoyilin/035.md","filePath":"zh/classics/jiaoyilin/035.md"}'),l={name:"zh/classics/jiaoyilin/035.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><h3 id="晉-1" tabindex="-1">晉 <a class="header-anchor" href="#晉-1" aria-label="Permalink to “晉”">​</a></h3><h3 id="晉之乾" tabindex="-1">晉之乾 <a class="header-anchor" href="#晉之乾" aria-label="Permalink to “晉之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>一衣三冠，冠無所絆。元服不成，為身災患。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為衣，卦數一，故曰一衣。晉艮為冠，數三，故曰三冠，艮下坤，坤坼，故曰冠無所絆、曰元服不成。坤為身、為災患。○第二三句宋元本作&quot;無所加元，衣服不來&quot;，身作我，均依汲古。</p><h3 id="晉之坤" tabindex="-1">晉之坤 <a class="header-anchor" href="#晉之坤" aria-label="Permalink to “晉之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《履》、《比》之《無妄》，履用伏象。謙與無妄皆以震為足，此則以坤形象百足蟲，坤為百也。</p><h3 id="晉之屯" tabindex="-1">晉之屯 <a class="header-anchor" href="#晉之屯" aria-label="Permalink to “晉之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>魚蛇之怪，大人憂懼。梁君好城，失其安居。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為魚、為蛇，坎為怪，震為大人，坎為憂懼，震為君，震木為梁，故曰梁君。艮為城，正覆艮，故曰好城。艮為安居，坎失，故曰失其安居。元本註：春秋：梁君好城而弗處，卒亡其國。</p><h3 id="晉之蒙" tabindex="-1">晉之蒙 <a class="header-anchor" href="#晉之蒙" aria-label="Permalink to “晉之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>少無韁輔，長不見母。勞心遠思，自傷憂苦。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為少，兌為輔、為剛，兌伏故無。震為長，坤為母，坎隱故不見。坎為勞、為心、為思、為憂苦。</p><h3 id="晉之需" tabindex="-1">晉之需 <a class="header-anchor" href="#晉之需" aria-label="Permalink to “晉之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>前涉溽暑，解不可取。離門二里，敗我利市。老牛病馬，去之何悔。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為前、為行，離為暑，與坎連，故曰溽暑。解懈同。《詩大雅》&quot;不解於位&quot;註：怠惰也，坎勞故曰解不可取。乾為門，兌卦數二，故曰離門二里。巽為利市，二至四巽覆，故敗我利市。離為牛，乾老故曰老牛。乾為馬，坎病，故曰病馬。坎為悔，在外，故去之無悔。○門二，宋元本作河三，依汲古。涉，汲古作不，依宋元本。</p><h3 id="晉之訟" tabindex="-1">晉之訟 <a class="header-anchor" href="#晉之訟" aria-label="Permalink to “晉之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>君明有德，登天大祿。布政施惠，以成恩福。中子南游，翱翔未復。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為君、為德，離火為明，乾為天、為大祿，巽為政命，巽風為佈施，乾為恩福。坎為中男，乾為南、為行，故曰中子南游。離為飛，故曰翱翔，坎陷故曰未復，言未歸也。○成，宋元本作感，依汲古。</p><h3 id="晉之師" tabindex="-1">晉之師 <a class="header-anchor" href="#晉之師" aria-label="Permalink to “晉之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>嘵然唯諾，敬上尊客。執恭除患，禦侮致福。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎正反兩兌口，震為聲，故曰嘵然唯諾。震為客，伏乾為貴，故曰尊容。乾惕為敬，坎為患，震解故除患。坤為御、為侮，震樂故致福。</p><h3 id="晉之比" tabindex="-1">晉之比 <a class="header-anchor" href="#晉之比" aria-label="Permalink to “晉之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>黍稷禾稻，垂秀方造。中旱不雨，傷風病槁。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤為茅茹，故為黍稷禾稻。造，作也，言苗秀興起也。坎為中、為雨，艮火故中旱不雨。坤為風，故傷風病槁。</p><h3 id="晉之小畜" tabindex="-1">晉之小畜 <a class="header-anchor" href="#晉之小畜" aria-label="Permalink to “晉之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>三羸六罷，不能越跪。東賈失馬，往返勞苦。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震數三，坎數六，坎病故羸，坎勞故罷。震為越跪、為東、為賈、為馬，坎失故失馬。震為往反，坎為勞苦。○羸，宋本作嬴，依元本、汲古。</p><h3 id="晉之履" tabindex="-1">晉之履 <a class="header-anchor" href="#晉之履" aria-label="Permalink to “晉之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>倚立相望，引衣欲裝。陰雲蔽日，暴雨降集。使道不通，阻我歡會。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為倚立，艮為望，正反艮故曰相望。坤為衣裳，艮手為引、為裝，裝朿也。坤為陰雲、為蔽，離日，故陰雲蔽日。坎為暴雨、為降集。震為道，坎塞故不通，故阻我歡會。坤我震歡也。○裝，宋元本作莊。降，宋本作祈，元本作所。阻，宋元本作降。會，元本作惠。五六句宋元本倒置，均依汲古。</p><h3 id="晉之泰" tabindex="-1">晉之泰 <a class="header-anchor" href="#晉之泰" aria-label="Permalink to “晉之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>高腳疾步，受肩善趨。日走千里，賈市有得。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>中爻震為足，故曰腳步，震躁，故高腳疾步、故善趨、故日走千里。震伏巽為賈市，巽利故有得。坤為受，伏艮為肩。○善，汲古作喜，依宋元本。</p><h3 id="晉之否" tabindex="-1">晉之否 <a class="header-anchor" href="#晉之否" aria-label="Permalink to “晉之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>北風寒涼，雨雪益冰。憂思不樂，哀悲傷心。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>中爻巽風，坤為北，乾為寒、為冰雪，故曰北風寒涼，雨雪益冰。乾惕故憂，震樂震倒故不樂。坤為哀悲、為心。</p><h3 id="晉之同人" tabindex="-1">晉之同人 <a class="header-anchor" href="#晉之同人" aria-label="Permalink to “晉之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>貞鳥雎鳩，執一無尤。寢門治理，君子悅喜。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>離為鳥、為鳩，通《師》。坎為尤，數一，震樂故執一無尤。坤為門、為寢、為理，震為君子、為悅喜。○雎，宋元本作鳴，依汲古。</p><h3 id="晉之大有" tabindex="-1">晉之大有 <a class="header-anchor" href="#晉之大有" aria-label="Permalink to “晉之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>蓼蕭露瀼，君子龍光。鳴鸞噰噰，福祿來同。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為薪、為蓼蕭，坎為露。艮為君子、為貴。龍，寵也，坤文為鸞，兌為鳴，乾為福祿。蓼蕭，義詳《恆》之《蹇》。○龍，汲古作寵，依宋元本。噰噰，宋元本作雍和，依汲古。</p><h3 id="晉之謙" tabindex="-1">晉之謙 <a class="header-anchor" href="#晉之謙" aria-label="Permalink to “晉之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>南行求福，與喜相得。封受上賞，鼎足輔國。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為行、為南，艮為求，震為福、為喜、為受，坤閉為封，艮為賞，陽在上，故曰上賞。震為足，數三，故曰鼎足。坤為國，艮伏兌，兌輔，故曰輔國。○封受，依宋本，汲古作受封。</p><h3 id="晉之豫" tabindex="-1">晉之豫 <a class="header-anchor" href="#晉之豫" aria-label="Permalink to “晉之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>桑葉腐蠹，衣敝如絡。女功不成，絲布為玉。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為桑葉，坎病，故腐蠹。坤為衣裳，坎破故敝。震伏巽，巽繩，故曰如絡、故曰絲布。坤為女，坤喪故功不成。震為玉絲，為玉者，言桑壞不能產絲，故值貴也。</p><h3 id="晉之隨" tabindex="-1">晉之隨 <a class="header-anchor" href="#晉之隨" aria-label="Permalink to “晉之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>左服易右，王良心歡，喜利從己。震左兌右。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>服者，夾轅之馬。震為馬。左服易右者，震為左，兌為右，言馬初在左，至上兌而右也。震為王，艮為良，故曰王良。坎為心，震為歡喜、為從，巽為利。王良，古善御者。○喜，宋元本作嘉，依汲古。</p><h3 id="晉之蠱" tabindex="-1">晉之蠱 <a class="header-anchor" href="#晉之蠱" aria-label="Permalink to “晉之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>壽考不忘，駕駟東行。三適陳宋，南賈楚荊。得利息長，旅身多罷，畏晝喜夜。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為壽考，震為馬，故曰駕駟。震東故東行。震為陳，艮為宋，震數三，故曰三適陳宋。互震為南，巽為賈、為楚荊，故曰南賈楚荊。巽為利、為長、為商旅，互大坎為罷、為畏、為夜，離為晝，晝動故畏，夜伏故喜。○駟，宋元本作騂，三作之，身作自，均依汲古。</p><h3 id="晉之臨" tabindex="-1">晉之臨 <a class="header-anchor" href="#晉之臨" aria-label="Permalink to “晉之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>羔羊皮革，君子朝服。輔政扶德，以合萬國。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌為羔羊，通《遯》。艮為皮、為革、為君子，坤為朝、為衣服，故曰君子朝服。兌為輔，坤為政，艮手為扶，乾為德，故曰輔政扶德。坤為國，坤眾故曰萬國，坤閉為合，故曰以合萬國。《詩召南》：&quot;羔羊之皮，素絲五紽；羔羊之革，素絲五緎&quot;，美召公也。○國，宋元作福，依汲古。革，各本皆作弁，依《謙》之《離》校。</p><h3 id="晉之觀" tabindex="-1">晉之觀 <a class="header-anchor" href="#晉之觀" aria-label="Permalink to “晉之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>鸇鳩徒巢，西至平州。遭逢雷塌，破我葦廬。室家饑寒，思吾故初。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為鸇，坤文為鳩，艮為巢，伏震為徙，故曰鸇鳩徒巢。兌為西，坤為州、為平，震為雷塌，兌折為破，艮為廬，巽為葦，故曰葦廬。艮為室家，坤為飢，乾為寒，故曰室家饑寒。坤為吾，乾為初。○第四句宋本、汲古廬作蘆，依元本。</p><h3 id="晉之噬嗑" tabindex="-1">晉之噬嗑 <a class="header-anchor" href="#晉之噬嗑" aria-label="Permalink to “晉之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>大尾小頭，重不可搖。上弱下強，陰制其雄。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為尾，震大，故曰大尾。坎為首，艮為小，故曰小頭。坤為重，坎陷，故重不可搖。艮上震下，艮小故弱，震長故強，四陽陷陰中，故曰陰制其雄。</p><h3 id="晉之賁" tabindex="-1">晉之賁 <a class="header-anchor" href="#晉之賁" aria-label="Permalink to “晉之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>疏足息肩，有所忌難。金城銅郭，以鐵為關。藩屏自衛，安止無患。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為足，艮為肩，坎為忌難，艮為城郭，三至上正反兩艮，故又為關。艮為金，故曰金、曰銅、曰鐵。艮為藩屏、為安止，坎為患，安止故無患。</p><h3 id="晉之剝" tabindex="-1">晉之剝 <a class="header-anchor" href="#晉之剝" aria-label="Permalink to “晉之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>天命玄鳥，下生大商。造定四表，享國久長。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>通《夬》。乾為天，兌為言，故曰天命。乾為立，艮為黔喙、為鳥，故曰玄鳥。玄鳥者，燕也。兌為燕。震為生，震反，故下生。震為子，故生商。商，子姓也。艮為定、為表，伏兌數四，坤為國，故曰造定四表。艮為久長，據《詩商頌》箋&quot;高辛氏妃簡狄吞卵生契，為商祖&quot;。</p><h3 id="晉之復" tabindex="-1">晉之復 <a class="header-anchor" href="#晉之復" aria-label="Permalink to “晉之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>賦斂重數，政為民賊。杼柚空虛，我去其室。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤聚故曰賦斂，重坤故曰重數。坤為政、為民，伏巽為賊。震為杼柚。《詩》&quot;杼柚其空&quot;《箋》雲：杼，持緯者；柚，受輕者也。杼柚上下震動，故取象於震。坤虛，艮為室，艮倒故去室。○斂，元本訛鈠，依宋本。</p><h3 id="晉之無妄" tabindex="-1">晉之無妄 <a class="header-anchor" href="#晉之無妄" aria-label="Permalink to “晉之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>陰陽隔塞，許嫁不答。宛丘新台，悔往嘆息。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>初陽伏陰下，艮止，故曰隔塞，女嫁曰歸。震為歸、為言，故許嫁。二至四震反，故曰不答。艮為丘、為台，宛丘，《陳風》篇名，悔嫁非其人而作也。震為嘆息，毛詩謂刺陳幽公淫亂無度。新台，《邶詩》篇名，毛謂刺衛宣公娶其子伋妻，國人惡之，林意似謂婦為夫棄也。</p><h3 id="晉之大畜" tabindex="-1">晉之大畜 <a class="header-anchor" href="#晉之大畜" aria-label="Permalink to “晉之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>願望登虛，意常欲逃。賈辛丑惡，妻不安夫。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為丘墟、為望，震為登，故曰願望登虛。震為逃，伏坤為意，震伏巽，巽為商賈，納辛，故曰賈辛。兌為醜惡，震夫兌妻，兌毀折而躁，故不安。《左氏昭二十八年》：&quot;昔賈大夫惡，娶妻而美，三年不言不笑。&quot;辛，大夫名。</p><h3 id="晉之頤" tabindex="-1">晉之頤 <a class="header-anchor" href="#晉之頤" aria-label="Permalink to “晉之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>踧行竊視，有所畏避。蔽目伏藏，以夜為利。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為踧行，艮為視，坤藏故竊視，故有所畏避。艮為目，坤為夜、為利。</p><h3 id="晉之大過" tabindex="-1">晉之大過 <a class="header-anchor" href="#晉之大過" aria-label="Permalink to “晉之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>信敏恭謙，敬鬼尊神。五嶽西瀆，克厭帝心，受福宜年。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為信敏，伏坤為恭謙，乾為惕，故曰敬，伏坤故曰鬼。乾為神，兌伏艮，艮為尊，故曰敬鬼尊神。艮為岳，巽卦數五，故曰五嶽。互大坎為河川，乾亦為江河，巽後天數四，故曰四瀆。坤為心，巽伏震，震帝故曰帝心。震為福，坤為受、為歲，故曰受福宜年。</p><h3 id="晉之坎" tabindex="-1">晉之坎 <a class="header-anchor" href="#晉之坎" aria-label="Permalink to “晉之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>懸懸南海，去家萬里。飛兔腰褭，一日見母，除我憂悔。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為海，伏離，故曰南海。震為萬里，故曰懸懸。艮為家，震為馬、為兔，坎為腰，故曰飛兔腰褭。飛兔腰褭，皆良馬名。離日，坎數一，故曰一日。本卦坤體，坤為母，乾二五之坤，故見母。坎為憂悔，震為除。</p><h3 id="晉之離" tabindex="-1">晉之離 <a class="header-anchor" href="#晉之離" aria-label="Permalink to “晉之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>雖污不辱，因何跣足。童子褰衣，五步平復。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。坎為污，坤為辱，坎折坤，故不辱。跣足者，赤足也。震足坎赤，故曰跣足。艮為童子，艮手為褰，震為衣，故曰褰衣。震為步，坎數五，坎平，故曰五步平復。○跣，宋元本作洗，步作年，依汲古。</p><h3 id="晉之咸" tabindex="-1">晉之咸 <a class="header-anchor" href="#晉之咸" aria-label="Permalink to “晉之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>宮城立見，衣就袂裾。恭謙自衛，終無禍尤。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。艮為宮城，震立兌見，艮為衣，震口為袂、為裾，巽為恭謙，震為警衛，坤為自、為禍尤，震解故無禍尤。○裾，宋元本作裙，依汲古。</p><h3 id="晉之恒" tabindex="-1">晉之恒 <a class="header-anchor" href="#晉之恒" aria-label="Permalink to “晉之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>敝笱在梁，不能得魚。望食千里，所至空虛。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為繩故為笱。笱，罟也。巽下斷故曰敝。艮為梁，巽為魚，巽敝漏故無得。伏艮為望，震為粒粟、為食、為千里，震為虛，故所至空虛。首句齊風語。○食，宋元本作貧，依汲古。</p><h3 id="晉之遯" tabindex="-1">晉之遯 <a class="header-anchor" href="#晉之遯" aria-label="Permalink to “晉之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>千里騂駒，為王服車。嘉其驪榮，君子有成。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為馬、為赤，故曰騂，艮少為駒，乾為千里，故曰千里騂駒。乾為王，二至四通震，震為車、為服，乾為嘉榮，艮為君子、為成。</p><h3 id="晉之大壯" tabindex="-1">晉之大壯 <a class="header-anchor" href="#晉之大壯" aria-label="Permalink to “晉之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>鼎足承德，嘉謀生福。為王開庭，得心所欲。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾為德，震為足，數三，故曰鼎足。乾為福、為生、為嘉、為王、為開，伏艮為庭，兌悅故得所欲。</p><h3 id="晉之晉" tabindex="-1">晉之晉 <a class="header-anchor" href="#晉之晉" aria-label="Permalink to “晉之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>銷鋒鑄耜，休牛放馬。甲兵解散，夫婦相保。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為鋒耜，離火為銷、為鑄，離牛坎馬，艮止故休放。離為甲兵，坎水克火，故解散。坎夫離婦，坤聚艮安，故相保。</p><h3 id="晉之明夷" tabindex="-1">晉之明夷 <a class="header-anchor" href="#晉之明夷" aria-label="Permalink to “晉之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>右手無合，獨折左指。禹湯失佐，事功不立。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>艮為手、為指，先天坎西，故曰右手，艮覆故指折。震左，坎折，坤寡，故曰獨折左指。震為王，故曰禹，水在火上故曰湯。震佐坎失，故曰禹湯失佐。坤為事功不立。○佐，汲古作位，依宋元本。</p><h3 id="晉之家人" tabindex="-1">晉之家人 <a class="header-anchor" href="#晉之家人" aria-label="Permalink to “晉之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>憂凶增累，患近不解。心意西東，事無成功。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>坎為憂憎、為凶、為累、為患，坎陷故不解。坎為心意、為西，離為東，故曰心意西東。巽為風，風散故事無成功。○增，宋元本作憎，依汲古。</p><h3 id="晉之睽" tabindex="-1">晉之睽 <a class="header-anchor" href="#晉之睽" aria-label="Permalink to “晉之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>東行食榆，困於枯株。夫妻無家，志窮為憂。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>離東兌食，坎為榆，皮可食。坎上下皆離，離科上槁故困於枯株，株枯則無皮可食。坎夫離妻，艮為家，艮伏故曰無家。坎為志、為憂。稽康《養生論》：&quot;榆令人瞑。&quot;《博物志》&quot;啖榆則眠不欲覺&quot;，又《禮內則》&quot;枌榆以滑之。&quot;古蓋常食榆皮。○夫，宋元本作失，依汲古。</p><h3 id="晉之蹇" tabindex="-1">晉之蹇 <a class="header-anchor" href="#晉之蹇" aria-label="Permalink to “晉之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>五經六紀，仁道所在。正月繁霜，獨不離咎。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>離為文，故曰經紀，坎納戌，數五，故曰五經。坎數六，故曰六紀。艮為道路、為反震，震為仁，故曰仁道所在。坎為中正、為月、為霜，重坎故曰正月繁霜。坎為獨、為咎。離，罹也，坎隱，故獨不罹咎。五經者，五常，《漢書賈誼傳》：&quot;六親有紀&quot;，六紀即六親也。《白虎通》：&quot;六紀者，諸父、兄弟、族人、諸舅、師長、朋友。&quot;正月，《小雅》篇名，憂亂而作。</p><h3 id="晉之解" tabindex="-1">晉之解 <a class="header-anchor" href="#晉之解" aria-label="Permalink to “晉之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>懈緩不前，怠惰失便。二至之戒，家無禍凶。刻木象形，聞言不信。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震往為前，坎陷故懈緩不前，故怠惰失便。坎為冬，至離為夏至，故曰二至。《復》象傳雲：先王以至日閉關，商旅不行。又《月令》&quot;是月齊戒掩身&quot;，故雲戒。坎為室家、為凶禍，知戒故無禍。刻木象形未詳。坎為聞，震為言，坎上下兩兌口相背，故雲不信。○怠惰，宋元本作熖怠，依汲古、局本。木字，宋本汲古作水，依元本。解懈古通。觀首二句焦氏似讀解為懈。</p><h3 id="晉之損" tabindex="-1">晉之損 <a class="header-anchor" href="#晉之損" aria-label="Permalink to “晉之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>仁愛篤厚，不以所忿。害其所子，從我舊都，日益富有。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為仁愛，艮為篤厚，乾為忿，乾三之上成艮故不忿。《象傳》所謂&quot;懲忿&quot;也。震子坤害，故害其所子。坤為都，伏乾為舊、為我，震為從，故曰從我舊都。坤輿為富有，艮為日，故曰日益富有。○從，汲古作徙，依宋元本。</p><h3 id="晉之益" tabindex="-1">晉之益 <a class="header-anchor" href="#晉之益" aria-label="Permalink to “晉之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>缺破不成，胎卵未生，弗見兆形。巽隕落，故缺破不成。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為胎卵，震生，坤拆為兆、為形，巽伏故弗見。</p><h3 id="晉之夬" tabindex="-1">晉之夬 <a class="header-anchor" href="#晉之夬" aria-label="Permalink to “晉之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>摧角不傷，雖折復長。秉德無愆，老賴榮光。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>艮為角，艮伏兌折，故摧角，然陽必長故摧而不傷，雖折而復長。乾為德、為老，陽長故無愆，故老而愈榮。○愆，宋元本作騫，依汲古。</p><h3 id="晉之姤" tabindex="-1">晉之姤 <a class="header-anchor" href="#晉之姤" aria-label="Permalink to “晉之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>乘桴浮海，免脫厄中，雖困無凶。通《復》。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>震為桴、為乘，坤為海，坤厄震出，故免脫，故雖困無凶。○浮，宋元本作渡，凶作咎，依汲古。</p><h3 id="晉之萃" tabindex="-1">晉之萃 <a class="header-anchor" href="#晉之萃" aria-label="Permalink to “晉之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>孔鸞鴛雛，鵕鵜鶘。翱翔紫淵，嘉禾之圃，君子以娛。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。震為竹、為孔，坤為文，故為鸞鴛，艮鳥故為鵕鵜鶘。卦為萃故多若是。震為翱翔，兌為淵，乾赤，故曰紫淵。震為嘉禾，艮為圃、為君子，震樂故娛。○鵕，宋元本作鵁鵝，依汲古。禾，元本作木，依宋本、汲古。</p><h3 id="晉之升" tabindex="-1">晉之升 <a class="header-anchor" href="#晉之升" aria-label="Permalink to “晉之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>甘露溫潤，眾來得願。樂易君子，不逢禍亂。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>兌為露、為潤，坤為眾，震樂，故眾來得願。通《無妄》。艮為君子，震樂乾易，故曰樂易君子。坤為禍亂，乾在外故不逢。○二三句宋元本倒置，依汲古。</p><h3 id="晉之困" tabindex="-1">晉之困 <a class="header-anchor" href="#晉之困" aria-label="Permalink to “晉之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>東騎墮落，千里獨宿。高岸為谷，陽失其室。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。震為東、為騎，坎陷故墮落。震為千里，坎為獨、為宿，故曰千里獨宿。艮為高岸，坎窞為谷，故曰高岸為谷。坎為室、為失，困剛掩，故曰陽失其室。《詩小雅》：&quot;高岸為谷，深谷為陵&quot;。</p><h3 id="晉之井" tabindex="-1">晉之井 <a class="header-anchor" href="#晉之井" aria-label="Permalink to “晉之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>八才既登，以成嘉功。尨降庭堅，國無災凶。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。後天艮數八，震為才、為登、為嘉、為功，艮為成，故曰以成嘉功。震為尨，艮為庭，尨降庭堅，乃八元之二人。庭堅，即皋陶字也。艮為國，坎為災凶，震樂故無。○嘉，宋元本作善，尨作厖，茲依汲古。</p><h3 id="晉之革" tabindex="-1">晉之革 <a class="header-anchor" href="#晉之革" aria-label="Permalink to “晉之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>邯鄲反言，父兄生患。意涉憂恨，卒死不還。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。二至上正覆兩震言相反，坤為國，故曰邯鄲反言。乾父震兄，坎為患，震生，故曰父兄生患。坎為憂恨、為水，坤亦為水，震為涉，艮為終，故曰竟涉憂恨。震為還，坤死，故曰卒死不還。案此似用《史記陳涉傳》事。邯鄲反言者，言武臣反，陳涉自立為趙王，涉欲系其家屬，後涉竟戰死不得還也。○宋元本革鼎在震艮後，非。</p><h3 id="晉之鼎" tabindex="-1">晉之鼎 <a class="header-anchor" href="#晉之鼎" aria-label="Permalink to “晉之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>玉銑鐵頤，倉庫空虛。賈市無盈，與利為仇。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>元本舊註鍾口兩旁曰銑，蓋乾為金玉，初至五正倒皆兌，兌為口，故曰玉銑鐵頤。頤亦口。卦通《屯》，屯互頤也。屯艮為倉庫，坤為空虛，巽為賈、為市、為利，坤虛故無盈，故與利為仇。坎為仇也。○玉銑，汲古作五銳，從宋元本。銳為矛屬，與下鐵頤不相聯屬，自以取兌象作銑為允當，自來校此書者不知以易象為標準，故當否皆不知，此所以多舛也。</p><h3 id="晉之震" tabindex="-1">晉之震 <a class="header-anchor" href="#晉之震" aria-label="Permalink to “晉之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>白鳥銜鉺，鳴呼其子。旋枝張翅，來從其母。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為白，互離為鳥，震口為銜，坎為鉺，故曰白鳥銜鉺。震為子、為鳴呼、為木、為枝、為張翅、為從、為來，坤為母，來從其母者，言陽反坤初也。○旋枝，宋元本作施技，依汲古。</p><h3 id="晉之艮" tabindex="-1">晉之艮 <a class="header-anchor" href="#晉之艮" aria-label="Permalink to “晉之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>學靈三年，聖且神明。先見善祥，嘉吉福慶。鳱鵠知來，告我無憂。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>學靈者，學語也。三至上正反兩震言相對，下震如何言，上即如言反答，故曰學靈。震為年，數三，故曰三年。坎為聖，震為帝、為神，艮為明，故曰聖且神明。震為善祥、為吉慶。艮為鳱鵠，震為來、為告，坎為憂，震出故無憂。○第五句宋本作餌吉知來，汲古作神馬來見，依《小畜》之《漸》校。又二三句元本作&quot;仁聖且神，明見善祥&quot;，今依宋本。嘉吉，元本作吉喜，汲古作吉盛，亦依宋本。鳱鵠，義詳《小畜》之《漸》。</p><h3 id="晉之漸" tabindex="-1">晉之漸 <a class="header-anchor" href="#晉之漸" aria-label="Permalink to “晉之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>雲孽蒸起，失其道理。傷害年谷，神君乏祀。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>坎為雲、為孽，下得艮火，故能蒸起。伏震為起、為道，坎為失，故失其道里。震為年谷，巽隕落，故曰傷害年谷。震為神、為君。○理應為里之訛，依顧校。</p><h3 id="晉之歸妹" tabindex="-1">晉之歸妹 <a class="header-anchor" href="#晉之歸妹" aria-label="Permalink to “晉之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>春耕有息，秋入利福。獻豜大豵，以樂成功。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為春、為耕、為生，故曰息。兌為秋，震為利福，秋收故曰入。坎為豕，故曰豜、曰豵。震為功、為樂也。○大疑作私。豳風言私其豵，獻豜於公。</p><h3 id="晉之豐" tabindex="-1">晉之豐 <a class="header-anchor" href="#晉之豐" aria-label="Permalink to “晉之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>羸豕躑躅，虎入都邑。遮遏左右，國門勑急。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>巽為豕，巽繩，故曰羸豕。震為躑躅，巽入，伏艮為都邑、為虎，故曰虎入邑都，艮止故遮遏。震左兌右，艮為國門，坎險故急。○震為勑，元本作敕，依汲古。</p><h3 id="晉之旅" tabindex="-1">晉之旅 <a class="header-anchor" href="#晉之旅" aria-label="Permalink to “晉之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>東行西維，南北善迷。逐旅失群，亡我襦衣。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為東、為行，兌為西，巽繩為維。維，系也。震南坎北，坎又為疑，故曰南北善迷。震為逐，陰以陽為伴，旅卦下二陰隨二陽，上一陰隨一陽，故曰逐旅。坤眾為群，坎為失言，否二升五，遺二陰在下，故曰失群。否上乾為衣，下坤為襦，今變旅，乾坤形變，故曰亡我襦衣。</p><h3 id="晉之巽" tabindex="-1">晉之巽 <a class="header-anchor" href="#晉之巽" aria-label="Permalink to “晉之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>居室之倫，夫婦和親。小人乘車，碩果失豢。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。中爻艮為居，坎為室，震夫巽婦，兌悅故和親。震為車、為人，艮為小，故曰小人乘車。艮為碩果，兩艮皆覆，故失豢。豢，養也。○汲古多&quot;車在夫家，不知孰是&quot;二句，依元本。</p><h3 id="晉之兌" tabindex="-1">晉之兌 <a class="header-anchor" href="#晉之兌" aria-label="Permalink to “晉之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>東方孟春，乘冰戴盆。懼危不安，終失所歡。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。中爻震為東、為孟春，坎為冰，震為乘，坎在下故乘冰。震為盆，艮為戴，故曰戴盆。坎為危懼，艮為終，兌為歡。○首二句謂當春暖戴盆行冰上，故危而不安也。古人以頭戴物，孟子所謂斑白者不負戴於道路也，汲古作載，非，依宋元本。失，宋元、汲古皆作身，依周本。</p><h3 id="晉之渙" tabindex="-1">晉之渙 <a class="header-anchor" href="#晉之渙" aria-label="Permalink to “晉之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>風吹塵起，十里無所。南國年傷，不可安處。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>巽為風，震口為吹，艮為沙石、為小，故為塵。震為起。艮為里，伏兌數十，故曰十里，坎隱故無所也。震為南，艮為國、為時，坎災風隕，故南國年傷。坎險故不安。</p><h3 id="晉之節" tabindex="-1">晉之節 <a class="header-anchor" href="#晉之節" aria-label="Permalink to “晉之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>重載傷車，婦女無夫。三十不室，獨坐廬空。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為車、為載，艮山，在山故曰重載，兌折故傷車。兌為婦女，震為夫，坎失故無夫。震數三，兌數十，艮為室，坎隱，故三十無室。坎為獨，艮為坐、為廬，離虛，故曰空廬。</p><h3 id="晉之中孚" tabindex="-1">晉之中孚 <a class="header-anchor" href="#晉之中孚" aria-label="Permalink to “晉之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>敗牛羸馬，與利為市，不我嘉喜。中爻艮為牛，震為馬，兌毀折，故曰敗、曰羸。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為利市，震為喜也。</p><h3 id="晉之小過" tabindex="-1">晉之小過 <a class="header-anchor" href="#晉之小過" aria-label="Permalink to “晉之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>月出阜東，山蔽其明。章甫薦屨，箕子佯狂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為東、為出，艮為阜，兌月在山上，故曰月出阜東。艮山巽伏故明隱，艮為冠，故曰章甫。震為履、為草，故曰薦屨。薦，草也。震為箕、為子、為狂，御章甫之禮冠而下躡草履，不恭甚矣，故曰佯狂。○薦屨，汲古訛憂僂，茲從宋元本。</p><h3 id="晉之既濟" tabindex="-1">晉之既濟 <a class="header-anchor" href="#晉之既濟" aria-label="Permalink to “晉之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>出入門所，與道開通。杞梁之信，不失日中。少季渡江，來歸其邦，疾病危亡。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《晉》象。艮為門、為道，坎為木、為杞，艮為梁，坎為信，離為為日中。艮為少季，坎為江，艮為邦，坎為疾病危亡。杞梁，齊大夫，襄二十三年齊與莒戰，杞梁夜入莒地，莒子賄杞梁，使勿死戰，杞梁曰：昏而受命，日中棄之，亦君之所惡也。少季未詳，或指吳季札，林語似此者甚多，不能強解也。</p><h3 id="晉之未濟" tabindex="-1">晉之未濟 <a class="header-anchor" href="#晉之未濟" aria-label="Permalink to “晉之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>邑居衛師，如轉蓬時，居之凶危。此仍用《晉》象。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>坤為眾、為兵、為師、為邑，坤為薪、為蓬，艮為時、為居，坎為凶危。○居，宋元本作兵，茲依汲古，均不協。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
